// Async data fetch directly in Server Component
export default async function Page({ params }) {
  const { id } = await params
  const post = await db.posts.findById(id)
  return <article>{post.title}</article>
}

// Pass serializable data to Client Component
import LikeButton from './like-button'
export default async function Page({ params }) {
  const post = await getPost((await params).id)
  return <LikeButton likes={post.likes} />
}

// Pass Server Component as children prop to Client Component
import Modal from './modal'     // 'use client'
import Cart from './cart'       // Server Component
export default function Page() {
  return <Modal><Cart /></Modal>
}

// Enforce server-only boundary
import 'server-only'
export async function getSecretData() {
  return fetch(url, { headers: { authorization: process.env.API_KEY } })
}

